package com.bank.pnl.model;

import java.math.BigDecimal;

// A profit-and-loss desk with a signed rupee result.
public class PnlNode {
    private final String deskName;
    private final BigDecimal result; // may be negative
    private PnlNode left;
    private PnlNode right;

    public PnlNode(String deskName, BigDecimal result) {
        this.deskName = deskName;
        this.result = result;
    }
    public String getDeskName() { return deskName; }
    public BigDecimal getResult() { return result; }
    public PnlNode getLeft() { return left; }
    public PnlNode getRight() { return right; }
    public void setLeft(PnlNode left) { this.left = left; }
    public void setRight(PnlNode right) { this.right = right; }
}
