package com.bank.pnl.service;

import com.bank.pnl.model.PnlNode;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds the most profitable connected run of desks (max path sum).
public class MaxPathSumService {
    private static final Logger log = Logger.getLogger(MaxPathSumService.class.getName());

    private BigDecimal best;

    public BigDecimal mostProfitableRun(PnlNode root) {
        // Start at the smallest possible so all-negative trees work.
        best = new BigDecimal("-1E18");
        gain(root);
        log.info(() -> "Most profitable connected run = " + best);
        return best;
    }

    // Returns the best single downward branch gain (clamped at 0) to the parent.
    private BigDecimal gain(PnlNode node) {
        if (node == null) {
            return BigDecimal.ZERO;
        }
        // Clamp each child's contribution at zero: refuse loss-making branches.
        BigDecimal leftGain = gain(node.getLeft()).max(BigDecimal.ZERO);
        BigDecimal rightGain = gain(node.getRight()).max(BigDecimal.ZERO);

        // Path that bends through this desk uses BOTH branches.
        BigDecimal bent = node.getResult().add(leftGain).add(rightGain);
        if (bent.compareTo(best) > 0) {
            best = bent;
            log.fine(() -> "New best run bends through " + node.getDeskName()
                    + " = " + bent);
        }
        // To the parent we can only offer a straight single branch.
        return node.getResult().add(leftGain.max(rightGain));
    }
}
