package com.bank.pnl;

import com.bank.pnl.model.PnlNode;
import com.bank.pnl.service.MaxPathSumService;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class MaxPathApplication {
    private static final Logger log = Logger.getLogger(MaxPathApplication.class.getName());

    public static void main(String[] args) {
        // Best run bends through Mid: Left(200)+Mid(100)+Right(300) = 600.
        // The loss desk is correctly excluded.
        PnlNode mid = new PnlNode("Mid", new BigDecimal("100"));
        PnlNode left = new PnlNode("Left", new BigDecimal("200"));
        PnlNode right = new PnlNode("Right", new BigDecimal("300"));
        PnlNode loss = new PnlNode("Loss", new BigDecimal("-500"));
        mid.setLeft(left);
        mid.setRight(right);
        right.setRight(loss);

        MaxPathSumService service = new MaxPathSumService();
        log.info("NBI most profitable connected run: "
                + service.mostProfitableRun(mid));
    }
}
